WITH enriched AS (SELECT id, device_code, reading_ts, temp_c, humidity, pressure, status_bits, firmware, SUM(pressure) OVER (ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_pressure, LEAD(status_bits, 2) OVER (PARTITION BY device_code ORDER BY reading_ts, id) AS next_status_bits, LAST_VALUE(pressure, TRUE) OVER (PARTITION BY device_code ORDER BY pressure, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_pressure, SUM(temp_c) OVER (PARTITION BY device_code ORDER BY pressure, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_temp_c FROM device_readings) SELECT DATE_TRUNC('HOUR', reading_ts) AS hour_window, COUNT(*) AS num_rows, STDDEV_SAMP(temp_c) AS temp_c_stddev, SUM(CASE WHEN device_code = 'DV-02' THEN running_pressure ELSE 0 END) AS dv_02_running_pressure, COUNT_IF(device_code = 'DV-02') AS dv_02_events, PERCENTILE_APPROX(running_pressure, ARRAY(0.25, 0.5, 0.75)) AS running_pressure_quartiles, SORT_ARRAY(COLLECT_SET(device_code)) AS device_code_list FROM enriched GROUP BY CUBE (DATE_TRUNC('HOUR', reading_ts)) ORDER BY num_rows DESC NULLS LAST;
